#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Writes app/src/RevivalInfo.inc from the VERSION file (generated, do not edit).

VERSION holds a semantic version such as 0.1.0-beta.1; the program shows it as "0.1.0 beta.1"."""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(ROOT, "app", "src", "RevivalInfo.inc")


def main():
    ver = open(os.path.join(ROOT, "VERSION"), encoding="utf-8").read().strip()
    shown = ver.replace("-", " ", 1)
    text = ("// SPDX-License-Identifier: GPL-2.0-or-later\n"
            "// Generated by tools/gen_version.py from the VERSION file; do not edit.\n"
            "const\n"
            "  revival_version = '%s';\n"
            "  revival_version_text = '%s';\n" % (ver, shown))
    old = open(OUT, encoding="utf-8").read() if os.path.exists(OUT) else None
    if old != text:
        with open(OUT, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(text)
        print("wrote", OUT, file=sys.stderr)


main()
